function Live3DV2_13500850:OnDestroy()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- ====================================================== 

-- 在 mainForRuntime Init() 尾部被调用
function Live3DV2_13500850:OnMainInitEnd( mainForRuntime_ ) 
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    self.mainForRuntime = mainForRuntime_
    self.uiMain = mainForRuntime_.uiMain  -- Env
    self.uiMainTF = self.uiMain.controller.gameObject.transform
    self.baseJson = mainForRuntime_.baseJson
    ---

    local touchTipKey = "200S_TouchShoulder"

    local TipTouchNum = 0
    local retTable = {}
    Events.Broadcast(IdolLive3D_States.EventGetUITouchTip, touchTipKey, retTable )
    if isNotNull(retTable.ret) then 
        TipTouchNum = retTable.ret.touchedNum
        if type(TipTouchNum) ~= "number" then 
            printError("TipTouchNum 值异常: ".. tostring(TipTouchNum))
            TipTouchNum = 0
        end 
    end 
    local isPosBtnGray = (TipTouchNum==0)

    -- pos btn: show and gray  
    Events.Broadcast(IdolLive3D_States.EventSetUICustomShow, Live3D_UIKey.stageJumpBtn_pos, true, 0, true )
    Events.Broadcast(IdolLive3D_States.EventSetUICustomGray, Live3D_UIKey.stageJumpBtn_pos, isPosBtnGray, true )

    -- cam btn: show and gray  
    Events.Broadcast(IdolLive3D_States.EventSetUICustomShow, Live3D_UIKey.stageJumpBtn_cam, true, 0, true )
    Events.Broadcast(IdolLive3D_States.EventSetUICustomGray, Live3D_UIKey.stageJumpBtn_cam, false, true )

    ---
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        [IdolLive3D_States.EventFirstActiveUITouchTip] = function( uiTouchTipKey )
            if string.lower(uiTouchTipKey) == string.lower(touchTipKey) then 
                Events.Broadcast(IdolLive3D_States.EventSetUICustomGray, Live3D_UIKey.stageJumpBtn_pos, false, true )
            end 
        end,
    })
end



